def comps(I,v):
    H=len(I);W=len(I[0]);seen=set();res=[]
    for x in range(H):
        for y in range(W):
            if I[x][y]==v and (x,y) not in seen:
                st=[(x,y)];cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in cells:continue
                    cells.add((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            c2=(a+da,b+db)
                            if 0<=c2[0]<H and 0<=c2[1]<W and I[c2[0]][c2[1]]==v:st.append(c2)
                seen|=cells;res.append(sorted(cells))
    return res
