def sigs(I,v):
    cs=comps(I,v); res=[]
    for c in cs:
        m=min(c)
        cells=frozenset((x-m[0],y-m[1]) for x,y in c)
        h=max(x for x,y in cells)+1; w=max(y for x,y in cells)+1
        res.append((len(cells),(h,w),cells))
    return sorted(res,key=lambda t:t[0])
